"use client";

import { FormEvent, useEffect, useMemo, useState, type ChangeEvent } from "react";
import { useRouter } from "next/navigation";
import DashboardSelect from "@/components/dashboard/Select";
import DropdownEnhancer from "@/components/dashboard/DropdownEnhancer";
import CustomerManager from "@/components/dashboard/CustomerManager";
import SalesWorkspaceUpdated from "@/components/dashboard/SalesWorkspaceUpdated";
import DraftWorkspace from "@/components/dashboard/DraftWorkspace";
import { productCategories } from "@/lib/product-categories";
import type { Customer, Currency, ProductCategory } from "@/lib/types";

type Module = "dashboard" | "analytics" | "crm" | "customers" | "inventory" | "sales" | "orchestration" | "draft";
type Product = { id: string; name: string; category?: ProductCategory; details?: Record<string, string>; sku: string; price: number; currency?: Currency; stock: number; reorderLevel: number };
type Sale = { id: string; productId: string; productName: string; quantity: number; total: number; currency?: Currency; customerId?: string; customerName: string; status?: "SOLD" | "RETURNED" | "REFUNDED"; note?: string; createdAt: string };
type Conversation = { id: string; channel: string; customerName: string; customerAddress: string; status: string; lastMessageAt: string };
type CrmMessage = { id: string; direction: "INBOUND" | "OUTBOUND"; senderName: string; body: string; status: string; createdAt: string };
type Me = { user: { id: string; name: string; email: string; role: string }; workspace: { name: string; plan: string } };
type Analytics = { revenue: number; orders: number; units: number; bestSellers: { name: string; units: number }[] };
type Period = "3D" | "7D" | "1M" | "3M" | "1Y" | "YTD";
const periodLabels: Record<Period, string> = { "3D": "3 days", "7D": "7 days", "1M": "1 month", "3M": "3 months", "1Y": "1 year", YTD: "Year to date" };
const currencies: { code: Currency; label: string }[] = [{ code: "USD", label: "USD · US Dollar" }, { code: "PHP", label: "PHP · Philippine Peso" }, { code: "EUR", label: "EUR · Euro" }, { code: "GBP", label: "GBP · Pound Sterling" }, { code: "JPY", label: "JPY · Japanese Yen" }, { code: "CNY", label: "CNY · Chinese Yuan" }];
const currencyRates: Record<Currency, number> = { USD: 1, PHP: 58, EUR: 0.92, GBP: 0.79, JPY: 150, CNY: 7.2 };
function formatMoney(value: number, currency: Currency) { return new Intl.NumberFormat(undefined, { style: "currency", currency, maximumFractionDigits: currency === "JPY" ? 0 : 2 }).format(value); }
function convertMoney(value: number, from: Currency | undefined, to: Currency) { return (value / currencyRates[from || "USD"]) * currencyRates[to]; }
function filterSalesByPeriod(sales: Sale[], period: Period) { const now = new Date(); const start = new Date(now); if (period === "YTD") start.setMonth(0, 1); else if (period === "3D") start.setDate(now.getDate() - 2); else if (period === "7D") start.setDate(now.getDate() - 6); else if (period === "1M") start.setMonth(now.getMonth() - 1); else if (period === "3M") start.setMonth(now.getMonth() - 3); else start.setFullYear(now.getFullYear() - 1); start.setHours(0, 0, 0, 0); return sales.filter((sale) => (sale.status || "SOLD") === "SOLD" && new Date(sale.createdAt) >= start); }

function CrmInboxWithSearch({ conversations, messages, selected, setSelected, filter, setFilter, reply, setReply, onReply }: { conversations: Conversation[]; messages: CrmMessage[]; selected: string; setSelected: (value: string) => void; filter: string; setFilter: (value: string) => void; reply: string; setReply: (value: string) => void; onReply: (event: FormEvent) => void }) {
  const [query, setQuery] = useState("");
  const matches = conversations.filter((item) => (filter === "ALL" || item.channel === filter) && `${item.customerName} ${item.customerAddress} ${item.channel}`.toLowerCase().includes(query.toLowerCase()));
  const conversation = conversations.find((item) => item.id === selected);
  return <div className="dashboard-card grid min-h-[620px] overflow-hidden rounded-2xl border border-white/[0.07] bg-[#101313] lg:grid-cols-[320px_1fr]"><aside className="border-b border-white/[0.07] lg:border-b-0 lg:border-r"><div className="p-5"><h3 className="font-black">CRM Inbox</h3><p className="mt-1 text-xs text-white/35">Search clients across every channel</p><label className="mt-5 flex items-center gap-2 rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-2.5 text-white/35"><Icon name="search" size={16} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search clients or platforms" className="w-full bg-transparent text-sm text-white outline-none placeholder:text-white/25" /></label><select value={filter} onChange={(event) => setFilter(event.target.value)} className="mt-3 w-full rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-2.5 text-xs text-white/65"><option value="ALL">All platforms</option>{["WHATSAPP", "WECHAT", "LINE", "MESSENGER", "VIBER", "TELEGRAM", "SMS", "GMAIL", "OUTLOOK"].map((channel) => <option key={channel}>{channel}</option>)}</select></div><div className="max-h-[470px] space-y-1.5 overflow-y-auto px-4 pb-4">{matches.map((item) => <button key={item.id} onClick={() => setSelected(item.id)} className={`w-full rounded-xl p-3 text-left transition ${selected === item.id ? "bg-primary/10 ring-1 ring-primary/25" : "hover:bg-white/[0.04]"}`}><div className="flex items-center justify-between gap-2"><span className="truncate text-sm font-bold">{item.customerName}</span><span className="text-[9px] font-black text-primary">{item.channel}</span></div><p className="mt-1 truncate text-[11px] text-white/35">{item.customerAddress}</p></button>)}{!matches.length && <p className="px-2 py-8 text-center text-xs text-white/30">No matching customers.</p>}</div></aside><section className="flex min-h-[620px] flex-col"><div className="p-5"><h3 className="font-black">{conversation?.customerName || "Select a conversation"}</h3><p className="mt-1 text-xs text-white/35">{conversation ? `${conversation.channel} · ${conversation.customerAddress}` : "Your connected channels will appear here."}</p></div><div className="flex-1 space-y-4 overflow-y-auto border-y border-white/[0.07] p-5">{messages.map((item) => <div key={item.id} className={`flex ${item.direction === "OUTBOUND" ? "justify-end" : "justify-start"}`}><div className={`max-w-[80%] rounded-2xl px-4 py-3 text-sm ${item.direction === "OUTBOUND" ? "bg-primary text-bg" : "bg-white/[0.05] text-white/80"}`}><p className="mb-1 text-[10px] font-bold opacity-60">{item.senderName} · {item.direction === "OUTBOUND" ? "You" : "Customer"}</p>{item.body}</div></div>)}</div><form onSubmit={onReply} className="flex gap-3 p-4"><input required disabled={!selected} value={reply} onChange={(event) => setReply(event.target.value)} placeholder={selected ? `Reply via ${conversation?.channel || "channel"}…` : "Select a conversation first"} className="min-w-0 flex-1 rounded-xl border border-white/[0.08] bg-white/[0.025] px-4 py-3 text-sm outline-none focus:border-primary disabled:opacity-40" /><button disabled={!selected} className="rounded-xl bg-primary px-4 text-sm font-black text-bg disabled:opacity-40">Send</button></form></section></div>;
}

const navItems: { id: Module; label: string; description: string; icon: string }[] = [
  { id: "dashboard", label: "Overview", description: "Workspace pulse", icon: "grid" },
  { id: "analytics", label: "Analytics", description: "Business performance", icon: "chart" },
  { id: "crm", label: "CRM inbox", description: "Customer conversations", icon: "chat" },
  { id: "customers", label: "Customer tracking", description: "Tracked customers", icon: "users" },
  { id: "inventory", label: "Inventory", description: "Products and stock", icon: "box" },
  { id: "sales", label: "Sales", description: "Orders and receipts", icon: "receipt" },
  { id: "orchestration", label: "Orchestration", description: "Growth team agents", icon: "users" },
  { id: "draft", label: "Draft", description: "Team conversation", icon: "chat" },
];

function Icon({ name, size = 18 }: { name: string; size?: number }) {
  const common = { width: size, height: size, viewBox: "0 0 24 24", fill: "none", stroke: "currentColor", strokeWidth: 1.8, strokeLinecap: "round" as const, strokeLinejoin: "round" as const };
  if (name === "grid") return <svg {...common}><rect x="3" y="3" width="7" height="7" rx="1" /><rect x="14" y="3" width="7" height="7" rx="1" /><rect x="3" y="14" width="7" height="7" rx="1" /><rect x="14" y="14" width="7" height="7" rx="1" /></svg>;
  if (name === "chart") return <svg {...common}><path d="M4 19V5M4 19h17" /><path d="m7 15 4-4 3 2 5-7" /></svg>;
  if (name === "chat") return <svg {...common}><path d="M20 11.5a7.5 7.5 0 0 1-8 7.5 8.4 8.4 0 0 1-3.2-.6L4 20l1.5-3.7A7.2 7.2 0 0 1 4 11.5 7.5 7.5 0 0 1 12 4a7.5 7.5 0 0 1 8 7.5Z" /><path d="M8 11h.01M12 11h.01M16 11h.01" /></svg>;
  if (name === "users") return <svg {...common}><circle cx="9" cy="8" r="3" /><path d="M3.5 19a5.5 5.5 0 0 1 11 0M16 11a2.5 2.5 0 1 0 0-5M16 14a5 5 0 0 1 4.5 5" /></svg>;
  if (name === "box") return <svg {...common}><path d="m12 3 8 4.5v9L12 21l-8-4.5v-9L12 3Z" /><path d="m4 7.5 8 4.5 8-4.5M12 12v9" /></svg>;
  if (name === "receipt") return <svg {...common}><path d="M5 3h14v18l-3-2-4 2-4-2-3 2V3Z" /><path d="M8 8h8M8 12h8M8 16h4" /></svg>;
  if (name === "plus") return <svg {...common}><path d="M12 5v14M5 12h14" /></svg>;
  if (name === "search") return <svg {...common}><circle cx="10.8" cy="10.8" r="6.8" /><path d="m16 16 5 5" /></svg>;
  if (name === "bell") return <svg {...common}><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4" /></svg>;
  if (name === "arrow") return <svg {...common}><path d="M5 12h14M13 6l6 6-6 6" /></svg>;
  if (name === "edit") return <svg {...common}><path d="m4 16-.8 4.8L8 20l11.5-11.5a2.8 2.8 0 0 0-4-4L4 16Z" /><path d="m13.5 6.5 4 4" /></svg>;
  if (name === "trash") return <svg {...common}><path d="M4 7h16M10 11v6M14 11v6M6 7l1 14h10l1-14M9 7V4h6v3" /></svg>;
  if (name === "eye") return <svg {...common}><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z" /><circle cx="12" cy="12" r="2.5" /></svg>;
  if (name === "logout") return <svg {...common}><path d="M10 4H5v16h5M14 8l4 4-4 4M18 12H9" /></svg>;
  return <svg {...common}><circle cx="12" cy="12" r="8" /></svg>;
}

export default function DashboardPage() {
  const router = useRouter();
  const [active, setActive] = useState<Module>("dashboard");
  const [mobileNav, setMobileNav] = useState(false);
  const [me, setMe] = useState<Me | null>(null);
  const [products, setProducts] = useState<Product[]>([]);
  const [analytics, setAnalytics] = useState<Analytics | null>(null);
  const [sales, setSales] = useState<Sale[]>([]);
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [crmMessages, setCrmMessages] = useState<CrmMessage[]>([]);
  const [selectedConversation, setSelectedConversation] = useState("");
  const [channelFilter, setChannelFilter] = useState("ALL");
  const [notice, setNotice] = useState("");
  const [product, setProduct] = useState({ name: "", category: "GENERAL" as ProductCategory, details: {} as Record<string, string>, sku: "", price: "", currency: "USD" as Currency, stock: "", reorderLevel: "5" });
  const [sale, setSale] = useState({ productId: "", quantity: "1", customerId: "", customerName: "" });
  const [reply, setReply] = useState("");
  const [invite, setInvite] = useState({ name: "", email: "", role: "SALES" });
  const [receiptSale, setReceiptSale] = useState<Sale | null>(null);
  const [showLogout, setShowLogout] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [notifications, setNotifications] = useState<string[]>([]);
  const [period, setPeriod] = useState<Period>("7D");
  const [displayCurrency, setDisplayCurrency] = useState<Currency>("USD");

  async function load() {
    const meResponse = await fetch("/api/me");
    if (!meResponse.ok) { router.push("/login"); return; }
    const current = await meResponse.json(); setMe(current);
    const [productResponse, analyticsResponse, salesResponse, inboxResponse, customerResponse] = await Promise.all([fetch("/api/products"), fetch("/api/analytics"), fetch("/api/sales"), fetch("/api/crm/conversations"), fetch("/api/customers")]);
    if (productResponse.ok) setProducts((await productResponse.json()).products);
    if (analyticsResponse.ok) setAnalytics(await analyticsResponse.json());
    if (salesResponse.ok) setSales((await salesResponse.json()).sales);
    if (inboxResponse.ok) { const inbox = await inboxResponse.json(); setConversations(inbox.conversations); if (!selectedConversation && inbox.conversations[0]) setSelectedConversation(inbox.conversations[0].id); }
    if (customerResponse.ok) setCustomers((await customerResponse.json()).customers);
  }

  useEffect(() => { load(); }, []);
  useEffect(() => { if (!selectedConversation) return; fetch(`/api/crm/messages?conversationId=${selectedConversation}`).then((r) => r.ok ? r.json() : null).then((data) => data && setCrmMessages(data.messages)); }, [selectedConversation]);
  useEffect(() => { if (!showNotifications) return; const close = (event: MouseEvent) => { const target = event.target as HTMLElement; if (!target.closest(".dashboard-notifications") && !target.closest('button[aria-label="Notifications"]')) setShowNotifications(false); }; document.addEventListener("mousedown", close); return () => document.removeEventListener("mousedown", close); }, [showNotifications]);

  const allowedModules = useMemo(() => {
    if (!me) return [] as Module[];
    if (me.user.role === "OWNER") return navItems.filter((item) => (item.id !== "orchestration" || me.workspace.plan === "GROWTH") && (item.id !== "draft" || me.workspace.plan === "GROWTH")).map((item) => item.id);
    const roles: Record<string, Module[]> = { SALES: ["dashboard", "inventory", "sales"], INVENTORY: ["dashboard", "inventory"], ANALYTICS: ["dashboard", "analytics", "inventory"], CRM: ["dashboard", "crm", "customers"] };
    const modules = roles[me.user.role] || ["dashboard"];
    return me.workspace.plan === "GROWTH" ? [...modules, "draft" as Module] : modules;
  }, [me]);

  useEffect(() => { if (me && !allowedModules.includes(active)) setActive(allowedModules[0] || "dashboard"); }, [active, allowedModules, me]);

  function changeModule(module: Module) { setActive(module); setMobileNav(false); setNotice(""); }
  function resultNotice(response: Response, data: { error?: string }, success: string) { const message = response.ok ? success : data.error || "Something went wrong."; setNotice(message); setNotifications((items) => [message, ...items].slice(0, 20)); if (response.ok) window.setTimeout(() => setNotice(""), 500); }

  async function addProduct(event: FormEvent) { event.preventDefault(); const response = await fetch("/api/products", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(product) }); const data = await response.json(); resultNotice(response, data, "Product added to inventory."); if (response.ok) { setProduct({ name: "", category: "GENERAL", details: {}, sku: "", price: "", currency: "USD", stock: "", reorderLevel: "5" }); load(); } }
  async function recordSale(event: FormEvent) { event.preventDefault(); if (!sale.customerId) { setNotice("Select a tracked customer before recording a sale."); return; } const response = await fetch("/api/sales", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(sale) }); const data = await response.json(); resultNotice(response, data, "Sale recorded and inventory updated."); if (response.ok) { setSale({ productId: "", quantity: "1", customerId: "", customerName: "" }); load(); } }
  async function replyToCustomer(event: FormEvent) { event.preventDefault(); if (!selectedConversation) return; const response = await fetch("/api/crm/messages", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ conversationId: selectedConversation, body: reply }) }); const data = await response.json(); resultNotice(response, data, "Reply queued for delivery."); if (response.ok) { setReply(""); load(); const messages = await fetch(`/api/crm/messages?conversationId=${selectedConversation}`); if (messages.ok) setCrmMessages((await messages.json()).messages); } }
  async function inviteAgent(event: FormEvent) { event.preventDefault(); const response = await fetch("/api/invitations", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(invite) }); const data = await response.json(); setNotice(response.ok ? `Invite created · ${data.invitation.code} · temporary password ${data.invitation.temporaryPassword}` : data.error); }
  async function logout() { await fetch("/api/auth/logout", { method: "POST" }); router.push("/"); }

  if (!me) return <main className="flex min-h-screen items-center justify-center bg-[#080909] text-sm text-white/50">Loading your workspace…</main>;
  const activeItem = navItems.find((item) => item.id === active) || navItems[0];
  const lowStock = products.filter((item) => item.stock <= item.reorderLevel);
  const canInvite = me.workspace.plan !== "STARTER" && me.user.role === "OWNER";
  const trackedCustomerConversations = customers.map((customer) => ({ id: customer.id, channel: "CUSTOMER", customerName: customer.name, customerAddress: customer.email || customer.phone || customer.address || "Tracked customer", status: "OPEN", lastMessageAt: customer.updatedAt }));

  return <main className="dashboard-shell h-screen overflow-hidden bg-[#080909] text-white selection:bg-primary selection:text-bg"><DropdownEnhancer />
    <div className="flex min-h-screen">
      <aside className={`fixed inset-y-0 left-0 z-50 w-[280px] -translate-x-full bg-[#0d0f0f] px-4 py-5 transition-transform lg:static lg:translate-x-0 ${mobileNav ? "translate-x-0" : ""}`}>
        <div className="flex items-center gap-3 px-3"><img src="/logo/dashboard-logo.png" alt="Orquestra dashboard" className="h-12 w-12 rounded-xl object-cover" /><div><p className="font-black tracking-tight">Orquestra</p><p className="text-[10px] uppercase tracking-[0.2em] text-white/35">Operating system</p></div></div>
        <nav className="mt-8"><p className="px-3 text-[10px] font-black uppercase tracking-[0.2em] text-white/25">Workspace</p><div className="mt-3 space-y-1">{navItems.filter((item) => allowedModules.includes(item.id)).map((item) => <button key={item.id} onClick={() => changeModule(item.id)} className={`group flex w-full items-center gap-3 rounded-2xl px-3 py-3 text-left transition ${active === item.id ? "text-primary" : "text-white/45 hover:text-primary"}`}><span className={active === item.id ? "text-primary" : "text-white/35 group-hover:text-primary"}><Icon name={item.icon} /></span><span><span className="block text-sm font-bold">{item.label}</span><span className={`mt-0.5 block text-[11px] ${active === item.id ? "text-primary/70" : "text-white/25 group-hover:text-primary/70"}`}>{item.description}</span></span></button>)}</div></nav>
      </aside>
      {mobileNav && <button aria-label="Close navigation" onClick={() => setMobileNav(false)} className="fixed inset-0 z-40 bg-black/60 lg:hidden" />}
      <div className="min-w-0 flex-1">
        <header className="sticky top-0 z-30 flex h-[76px] items-center justify-between bg-[#080909]/90 px-5 backdrop-blur-xl sm:px-8"><div className="flex items-center gap-3"><button aria-label="Open navigation" onClick={() => setMobileNav(true)} className="rounded-xl p-2 text-white/60 hover:bg-white/5 lg:hidden"><span className="block h-0.5 w-5 bg-current" /><span className="mt-1.5 block h-0.5 w-5 bg-current" /><span className="mt-1.5 block h-0.5 w-5 bg-current" /></button><div><p className="text-xs text-white/35">Workspace / <span className="text-white/70">{activeItem.label}</span></p><h1 className="mt-1 text-lg font-black tracking-tight sm:text-xl">{activeItem.label}</h1></div></div><div className="flex items-center gap-2 sm:gap-4"><div className="relative"><button aria-label="Notifications" onClick={() => setShowNotifications((open) => !open)} className="relative p-2 text-white/45 transition hover:text-primary"><Icon name="bell" size={19} />{notifications.length > 0 && <span className="absolute right-0.5 top-0.5 flex h-4 min-w-4 items-center justify-center rounded-full bg-primary px-1 text-[9px] font-black text-bg">{notifications.length > 9 ? "9+" : notifications.length}</span>}</button>{showNotifications && <div className="dashboard-notifications"><div className="flex items-center justify-between border-b border-white/[0.07] px-4 py-3"><p className="text-sm font-black">Activity</p><button onClick={() => setNotifications([])} className="text-[10px] font-bold text-primary">Clear all</button></div><div className="max-h-72 overflow-y-auto p-2">{notifications.length ? notifications.map((item, index) => <p key={`${item}-${index}`} className="dashboard-notification-item">{item}</p>) : <p className="px-3 py-8 text-center text-xs text-white/35">No recent activity.</p>}</div></div>}</div><div className="hidden h-8 w-px bg-white/10 sm:block" /><div className="flex items-center gap-2"><div className="hidden sm:block"><p className="text-xs font-bold">{me.user.name}</p><p className="text-[10px] text-white/35">{me.user.email}</p></div><button aria-label="Sign out" title="Sign out" onClick={() => setShowLogout(true)} className="ml-1 rounded-xl p-2 text-white/45 transition hover:bg-rose-400/10 hover:text-rose-300"><Icon name="logout" size={18} /></button></div></div></header>
        <div className="dashboard-content mx-auto h-[calc(100vh-76px)] max-w-[1440px] overflow-hidden px-5 py-7 sm:px-8 sm:py-9"><div className="mb-7 flex flex-wrap items-end justify-between gap-4"><div><p className="text-sm text-white/40">Good to see you, {me.user.name.split(" ")[0]}.</p><h2 className="mt-1 text-2xl font-black tracking-tight sm:text-3xl">{active === "dashboard" ? "Here’s your business pulse." : activeItem.description}</h2></div>{active === "dashboard" && <button onClick={() => changeModule("sales")} className="flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-black text-bg transition hover:bg-secondary"><Icon name="plus" size={16} /> Record sale</button>}</div>{notice && <div className="fixed right-6 top-20 z-[90] rounded-xl border border-primary/30 bg-[#10201d] px-4 py-3 text-sm font-bold text-primary shadow-xl"><span>{notice}</span></div>}
          {active === "dashboard" && <PeriodAwareOverview analytics={analytics} sales={sales} products={products} lowStock={lowStock} period={period} setPeriod={setPeriod} currency={displayCurrency} setCurrency={setDisplayCurrency} onModule={changeModule} />}
          {active === "analytics" && <AnalyticsPeriodPage sales={sales} period={period} setPeriod={setPeriod} currency={displayCurrency} setCurrency={setDisplayCurrency} />}
          {active === "inventory" && <InventoryCatalog products={products} lowStock={lowStock} product={product} setProduct={setProduct} onAdd={addProduct} onRefresh={load} setNotice={setNotice} />}
          {active === "sales" && <SalesWorkspaceUpdated products={products} conversations={trackedCustomerConversations} sales={sales} sale={sale} setSale={setSale} currency={displayCurrency} setCurrency={setDisplayCurrency} onSubmit={recordSale} onReceipt={setReceiptSale} onRefresh={load} setNotice={setNotice} />}
           {active === "customers" && <CustomerManager customers={customers} conversations={conversations} onRefresh={load} setNotice={setNotice} />}
           {active === "orchestration" && me.workspace.plan === "GROWTH" && me.user.role === "OWNER" && <OrchestrationPage setNotice={setNotice} />}
           {active === "draft" && me.workspace.plan === "GROWTH" && <DraftWorkspace setNotice={setNotice} />}
          {active === "crm" && <CrmInboxWithSearch conversations={conversations} messages={crmMessages} selected={selectedConversation} setSelected={setSelectedConversation} filter={channelFilter} setFilter={setChannelFilter} reply={reply} setReply={setReply} onReply={replyToCustomer} />}
        </div>{receiptSale && <ReceiptModal sale={receiptSale} onClose={() => setReceiptSale(null)} />}{showLogout && <LogoutModal onCancel={() => setShowLogout(false)} onConfirm={logout} />}
      </div>
    </div>
  </main>;
}

function Stat({ label, value, trend, icon, tone = "teal" }: { label: string; value: string; trend?: string; icon: string; tone?: "teal" | "violet" | "amber" | "blue" }) { const colors = { teal: "text-primary", violet: "text-violet-300", amber: "text-amber-300", blue: "text-sky-300" }; return <div className="dashboard-card rounded-2xl border border-white/[0.07] bg-[#101313] p-5"><div className="flex items-start justify-between"><span className={`flex h-9 w-9 items-center justify-center ${colors[tone]}`}><Icon name={icon} size={17} /></span>{trend && <span className="rounded-full bg-primary/10 px-2 py-1 text-[10px] font-bold text-primary">{trend}</span>}</div><p className="mt-5 text-xs text-white/40">{label}</p><p className="mt-1 text-2xl font-black tracking-tight">{value}</p></div>; }

function PeriodAwareOverview({ analytics, sales, products, lowStock, period, setPeriod, currency, setCurrency, onModule }: { analytics: Analytics | null; sales: Sale[]; products: Product[]; lowStock: Product[]; period: Period; setPeriod: (value: Period) => void; currency: Currency; setCurrency: (value: Currency) => void; onModule: (module: Module) => void }) { const buckets = chartBuckets(sales, period, currency); const max = Math.max(...buckets.map((bucket) => bucket.value), 1); const periodSales = filterSalesByPeriod(sales, period); const revenue = periodSales.reduce((sum, sale) => sum + convertMoney(sale.total, sale.currency, currency), 0); return <div className="space-y-6"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat label="Revenue" value={formatMoney(revenue, currency)} trend={periodLabels[period]} icon="chart" /><Stat label="Orders completed" value={String(periodSales.length)} trend={periodLabels[period]} icon="receipt" tone="violet" /><Stat label="Products tracked" value={String(products.length)} icon="box" tone="amber" /><Stat label="Units sold" value={String(periodSales.reduce((sum, sale) => sum + sale.quantity, 0))} trend={periodLabels[period]} icon="arrow" tone="blue" /></div><div className="grid gap-6 xl:grid-cols-[1.4fr_0.8fr]"><section className="dashboard-card rounded-2xl border border-white/[0.07] bg-[#101313] p-5 sm:p-6"><div className="flex items-start justify-between"><div><p className="text-xs text-white/40">Revenue overview</p><h3 className="mt-1 text-xl font-black">{periodLabels[period]}</h3></div><div className="flex flex-wrap items-center justify-end gap-3"><CurrencySelect currency={currency} setCurrency={setCurrency} /><PeriodSelect period={period} setPeriod={setPeriod} /></div></div><div className="mt-8 flex h-52 items-end gap-2 border-b border-white/[0.07]">{buckets.map((bucket) => <div key={bucket.label} className="group flex h-full flex-1 flex-col items-center justify-end gap-2"><span className="text-[10px] text-white/0 transition group-hover:text-white/60">{formatMoney(bucket.value, currency)}</span><div style={{ height: `${Math.max(bucket.value ? 8 : 2, bucket.value / max * 88)}%` }} className="w-full rounded-t-md bg-primary transition group-hover:bg-secondary" /></div>)}</div><div className="mt-3 flex justify-between gap-2 text-[10px] text-white/30">{buckets.map((bucket) => <span key={bucket.label} className="flex-1 text-center">{bucket.label}</span>)}</div></section><section className="dashboard-card rounded-2xl border border-white/[0.07] bg-[#101313] p-5 sm:p-6"><p className="text-xs text-white/40">Inventory health</p><h3 className="mt-1 text-xl font-black">{lowStock.length} <span className="text-sm font-medium text-white/35">alerts need attention</span></h3><div className="mt-7 space-y-5"><Health label="In stock" value={Math.max(products.length - lowStock.length, 0)} total={Math.max(products.length, 1)} color="bg-primary" /><Health label="Low stock" value={lowStock.length} total={Math.max(products.length, 1)} color="bg-amber-300" /><Health label="Out of stock" value={products.filter((item) => item.stock === 0).length} total={Math.max(products.length, 1)} color="bg-rose-400" /></div><button onClick={() => onModule("inventory")} className="mt-7 text-xs font-bold text-primary">Open inventory <Icon name="arrow" size={12} /></button></section></div><section className="dashboard-card rounded-2xl border border-white/[0.07] bg-[#101313] p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="text-xs text-white/40">Best sellers</p><h3 className="mt-1 text-lg font-black">Products driving revenue</h3></div><button onClick={() => onModule("analytics")} className="text-xs font-bold text-primary">Analytics <Icon name="arrow" size={12} /></button></div><div className="mt-5 grid gap-3 sm:grid-cols-2">{(analytics?.bestSellers || []).slice(0, 4).map((item, index) => <div key={item.name} className="flex items-center gap-3 rounded-xl bg-white/[0.025] p-3"><span className="w-8 text-center text-xs font-black text-primary">0{index + 1}</span><span className="flex-1 text-sm font-bold">{item.name}</span><span className="text-xs text-white/40">{item.units} units</span></div>)}</div></section></div>; }

function AnalyticsPeriodPage({ sales, period, setPeriod, currency, setCurrency }: { sales: Sale[]; period: Period; setPeriod: (value: Period) => void; currency: Currency; setCurrency: (value: Currency) => void }) { const buckets = chartBuckets(sales, period, currency); const max = Math.max(...buckets.map((bucket) => bucket.value), 1); const periodSales = filterSalesByPeriod(sales, period); const revenue = periodSales.reduce((sum, sale) => sum + convertMoney(sale.total, sale.currency, currency), 0); const best = Object.entries(periodSales.reduce<Record<string, number>>((out, sale) => { out[sale.productName] = (out[sale.productName] || 0) + sale.quantity; return out; }, {})).sort((a, b) => b[1] - a[1]).slice(0, 5); return <div className="space-y-6"><div className="flex flex-wrap items-center justify-end gap-3"><CurrencySelect currency={currency} setCurrency={setCurrency} /><PeriodSelect period={period} setPeriod={setPeriod} /></div><div className="grid gap-4 sm:grid-cols-3"><Stat label="Revenue" value={formatMoney(revenue, currency)} trend={periodLabels[period]} icon="chart" /><Stat label="Orders" value={String(periodSales.length)} icon="receipt" tone="violet" /><Stat label="Units sold" value={String(periodSales.reduce((sum, sale) => sum + sale.quantity, 0))} icon="arrow" tone="blue" /></div><div className="grid gap-6 xl:grid-cols-[1.05fr_0.95fr]"><section className="dashboard-card rounded-2xl border border-white/[0.07] bg-[#101313] p-5 sm:p-6"><p className="text-xs text-white/40">Business performance</p><h3 className="mt-1 text-xl font-black">Revenue · {periodLabels[period]}</h3><div className="mt-8 flex h-48 items-end gap-3 border-b border-white/[0.08]">{buckets.map((bucket) => <div key={bucket.label} className="group flex h-full flex-1 flex-col items-center justify-end gap-2"><span className="text-[10px] text-white/0 group-hover:text-white/60">{formatMoney(bucket.value, currency)}</span><div style={{ height: `${Math.max(bucket.value ? 8 : 2, bucket.value / max * 88)}%` }} className="w-full rounded-t-lg bg-primary transition group-hover:bg-secondary" /></div>)}</div><div className="mt-3 flex justify-between gap-2 text-center text-[10px] text-white/30">{buckets.map((bucket) => <span key={bucket.label} className="flex-1">{bucket.label}</span>)}</div></section><section className="dashboard-card rounded-2xl border border-white/[0.07] bg-[#101313] p-5 sm:p-6"><p className="text-xs text-white/40">Product performance</p><h3 className="mt-1 text-xl font-black">Best sellers</h3><div className="mt-6 space-y-4">{best.map(([name, units], index) => <div key={name} className="flex items-center gap-4"><span className="w-5 text-xs text-white/30">{index + 1}</span><span className="w-40 truncate text-sm font-bold">{name}</span><div className="h-2 flex-1 rounded-full bg-white/[0.06]"><div style={{ width: `${Math.max(15, 100 - index * 18)}%` }} className="h-full rounded-full bg-primary" /></div><span className="w-16 text-right text-xs text-white/45">{units}</span></div>)}</div></section></div></div>; }

function Health({ label, value, total, color }: { label: string; value: number; total: number; color: string }) { return <div><div className="flex justify-between text-xs"><span className="text-white/55">{label}</span><span className="font-bold">{value}</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-white/[0.06]"><div style={{ width: `${Math.min((value / total) * 100, 100)}%` }} className={`h-full rounded-full ${color}`} /></div></div>; }

function chartBuckets(sales: Sale[], period: Period, currency: Currency = "USD") { const count = period === "3D" ? 3 : period === "7D" ? 7 : period === "1M" ? 4 : period === "3M" ? 3 : period === "YTD" ? new Date().getMonth() + 1 : 12; const unit = period === "3D" || period === "7D" ? "day" : period === "1M" ? "week" : "month"; const step = 1; return Array.from({ length: count }, (_, index) => { const current = new Date(); current.setHours(0, 0, 0, 0); let start = new Date(current); let end = new Date(current); if (unit === "day") { start.setDate(current.getDate() - (count - 1 - index)); end = new Date(start); end.setDate(start.getDate() + 1); } else if (unit === "week") { start.setDate(current.getDate() - (count - 1 - index) * 7 - 6); end = new Date(start); end.setDate(start.getDate() + 7); } else { start = new Date(current.getFullYear(), current.getMonth() - (count - 1 - index) * step, 1); end = new Date(start.getFullYear(), start.getMonth() + step, 1); } const value = sales.filter((sale) => (sale.status || "SOLD") === "SOLD" && new Date(sale.createdAt) >= start && new Date(sale.createdAt) < end).reduce((sum, sale) => sum + convertMoney(sale.total, sale.currency, currency), 0); const label = unit === "month" ? start.toLocaleDateString(undefined, { month: "short" }) : unit === "week" ? `W${index + 1}` : start.toLocaleDateString(undefined, { weekday: "short" }); return { label, value }; }); }
function PeriodSelect({ period, setPeriod }: { period: Period; setPeriod: (value: Period) => void }) { return <DashboardSelect ariaLabel="Performance period" value={period} onChange={(value) => setPeriod(value as Period)} options={Object.entries(periodLabels).map(([value, label]) => ({ value, label }))} />; }
function CurrencySelect({ currency, setCurrency, label = "Currency" }: { currency: Currency; setCurrency: (value: Currency) => void; label?: string }) { return <label className="flex items-center gap-2 text-xs font-bold text-white/40"><span>{label}</span><DashboardSelect ariaLabel={label} value={currency} onChange={(value) => setCurrency(value as Currency)} options={currencies.map((item) => ({ value: item.code, label: item.label }))} /></label>; }

function OverviewWithPeriod({ analytics, sales, products, lowStock, period, setPeriod, onModule }: { analytics: Analytics | null; sales: Sale[]; products: Product[]; lowStock: Product[]; period: Period; setPeriod: (value: Period) => void; onModule: (module: Module) => void }) { const periodSales = filterSalesByPeriod(sales, period); const revenue = periodSales.reduce((sum, sale) => sum + sale.total, 0); const bars = Array.from({ length: 7 }, (_, index) => { const date = new Date(); date.setHours(0, 0, 0, 0); date.setDate(date.getDate() - (6 - index)); return periodSales.filter((sale) => new Date(sale.createdAt).toDateString() === date.toDateString()).reduce((sum, sale) => sum + sale.total, 0); }); const max = Math.max(...bars, 1); return <div className="space-y-6"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat label="Revenue" value={`$${revenue.toLocaleString(undefined, { minimumFractionDigits: 2 })}`} trend={periodLabels[period]} icon="chart" /><Stat label="Orders completed" value={String(periodSales.length)} trend={periodLabels[period]} icon="receipt" tone="violet" /><Stat label="Products tracked" value={String(products.length)} icon="box" tone="amber" /><Stat label="Units sold" value={String(periodSales.reduce((sum, sale) => sum + sale.quantity, 0))} trend={periodLabels[period]} icon="arrow" tone="blue" /></div><div className="grid gap-6 xl:grid-cols-[1.4fr_0.8fr]"><section className="dashboard-card rounded-2xl border border-white/[0.07] bg-[#101313] p-5 sm:p-6"><div className="flex items-start justify-between"><div><p className="text-xs text-white/40">Revenue overview</p><h3 className="mt-1 text-xl font-black">${revenue.toLocaleString(undefined, { minimumFractionDigits: 2 })}</h3></div><PeriodSelect period={period} setPeriod={setPeriod} /></div><div className="mt-8 grid h-48 grid-cols-7 items-end gap-2 border-b border-white/[0.07]">{bars.map((value, index) => <div key={index} className="group flex h-full flex-col items-center justify-end gap-2"><span className="text-[10px] text-white/0 transition group-hover:text-white/60">${value.toFixed(0)}</span><div style={{ height: `${Math.max(value ? 8 : 2, (value / max) * 82)}%` }} className={`w-full rounded-t-md transition group-hover:bg-secondary ${index === bars.length - 1 ? "bg-primary" : "bg-primary/25"}`} /></div>)}</div><div className="mt-3 grid grid-cols-7 text-center text-[10px] text-white/25">{bars.map((_, index) => <span key={index}>{index + 1}</span>)}</div></section><section className="dashboard-card rounded-2xl border border-white/[0.07] bg-[#101313] p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="text-xs text-white/40">Inventory health</p><h3 className="mt-1 text-xl font-black">{lowStock.length} <span className="text-sm font-medium text-white/35">alerts need attention</span></h3></div><button onClick={() => onModule("inventory")} className="text-xs font-bold text-primary">View all <Icon name="arrow" size={12} /></button></div><div className="mt-7 space-y-5"><Health label="In stock" value={Math.max(products.length - lowStock.length, 0)} total={Math.max(products.length, 1)} color="bg-primary" /><Health label="Low stock" value={lowStock.length} total={Math.max(products.length, 1)} color="bg-amber-300" /><Health label="Out of stock" value={products.filter((item) => item.stock === 0).length} total={Math.max(products.length, 1)} color="bg-rose-400" /></div></section></div><section className="dashboard-card rounded-2xl border border-white/[0.07] bg-[#101313] p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="text-xs text-white/40">Best sellers</p><h3 className="mt-1 text-lg font-black">Products driving revenue</h3></div><button onClick={() => onModule("analytics")} className="text-xs font-bold text-primary">Analytics <Icon name="arrow" size={12} /></button></div><div className="mt-5 grid gap-3 sm:grid-cols-2">{(analytics?.bestSellers || []).slice(0, 4).map((item, index) => <div key={item.name} className="flex items-center gap-3 rounded-xl bg-white/[0.025] p-3"><span className="w-8 text-center text-xs font-black text-primary">0{index + 1}</span><span className="flex-1 text-sm font-bold">{item.name}</span><span className="text-xs text-white/40">{item.units} units</span></div>)}{!analytics?.bestSellers.length && <p className="py-5 text-sm text-white/35">Sales data will appear here after your first order.</p>}</div></section></div>; }

function AnalyticsWithPeriod({ analytics, sales, period, setPeriod }: { analytics: Analytics | null; sales: Sale[]; period: Period; setPeriod: (value: Period) => void }) { const periodSales = filterSalesByPeriod(sales, period); const revenue = periodSales.reduce((sum, sale) => sum + sale.total, 0); const values = Array.from({ length: 7 }, (_, index) => { const date = new Date(); date.setHours(0, 0, 0, 0); date.setDate(date.getDate() - (6 - index)); return periodSales.filter((sale) => new Date(sale.createdAt).toDateString() === date.toDateString()).reduce((sum, sale) => sum + sale.total, 0); }); const max = Math.max(...values, 1); const best = Object.entries(periodSales.reduce<Record<string, number>>((out, sale) => { out[sale.productName] = (out[sale.productName] || 0) + sale.quantity; return out; }, {})).sort((a, b) => b[1] - a[1]).slice(0, 5); return <div className="space-y-6"><div className="flex items-center justify-end"><PeriodSelect period={period} setPeriod={setPeriod} /></div><div className="grid gap-4 sm:grid-cols-3"><Stat label="Revenue" value={`$${revenue.toFixed(2)}`} trend={periodLabels[period]} icon="chart" /><Stat label="Orders" value={String(periodSales.length)} icon="receipt" tone="violet" /><Stat label="Units sold" value={String(periodSales.reduce((sum, sale) => sum + sale.quantity, 0))} icon="arrow" tone="blue" /></div><section className="dashboard-card rounded-2xl border border-white/[0.07] bg-[#101313] p-5 sm:p-6"><div className="flex items-start justify-between"><div><p className="text-xs text-white/40">Business performance</p><h3 className="mt-1 text-xl font-black">Revenue · {periodLabels[period]}</h3></div><span className="rounded-full bg-primary/10 px-2.5 py-1 text-[10px] font-black uppercase tracking-wider text-primary">Sold sales</span></div><div className="mt-8 grid h-64 grid-cols-7 items-end gap-3 border-b border-white/[0.08]">{values.map((value, index) => <div key={index} className="group flex h-full flex-col items-center justify-end gap-2"><span className="text-[10px] text-white/0 transition group-hover:text-white/60">${value.toFixed(0)}</span><div style={{ height: `${Math.max(value ? 8 : 2, (value / max) * 86)}%` }} className={`w-full rounded-t-lg transition ${index === values.length - 1 ? "bg-primary" : "bg-primary/25 group-hover:bg-primary/60"}`} /></div>)}</div><div className="mt-3 grid grid-cols-7 text-center text-[10px] text-white/30">{values.map((_, index) => <span key={index}>{index + 1}</span>)}</div></section><section className="dashboard-card rounded-2xl border border-white/[0.07] bg-[#101313] p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="text-xs text-white/40">Product performance</p><h3 className="mt-1 text-xl font-black">Best sellers</h3></div><span className="text-xs text-white/35">Units sold</span></div><div className="mt-6 space-y-4">{best.map(([name, units], index) => <div key={name} className="flex items-center gap-4"><span className="w-5 text-xs text-white/30">{index + 1}</span><span className="w-40 truncate text-sm font-bold">{name}</span><div className="h-2 flex-1 rounded-full bg-white/[0.06]"><div style={{ width: `${Math.max(15, 100 - index * 18)}%` }} className="h-full rounded-full bg-primary" /></div><span className="w-16 text-right text-xs text-white/45">{units}</span></div>)}{!best.length && <p className="text-sm text-white/35">No sales data in this period.</p>}</div></section></div>; }


function AnalyticsPerformance({ analytics, sales }: { analytics: Analytics | null; sales: Sale[] }) { const days = Array.from({ length: 7 }, (_, index) => { const date = new Date(); date.setHours(0, 0, 0, 0); date.setDate(date.getDate() - (6 - index)); return date; }); const values = days.map((day) => sales.filter((sale) => (sale.status || "SOLD") === "SOLD" && new Date(sale.createdAt).toDateString() === day.toDateString()).reduce((sum, sale) => sum + sale.total, 0)); const max = Math.max(...values, 1); return <div className="space-y-6"><div className="grid gap-4 sm:grid-cols-3"><Stat label="Revenue" value={`$${(analytics?.revenue || 0).toFixed(2)}`} trend="All time" icon="chart" /><Stat label="Orders" value={String(analytics?.orders || 0)} icon="receipt" tone="violet" /><Stat label="Units sold" value={String(analytics?.units || 0)} icon="arrow" tone="blue" /></div><section className="rounded-2xl border border-white/[0.07] bg-[#101313] p-5 sm:p-6"><div className="flex items-start justify-between"><div><p className="text-xs text-white/40">Business performance</p><h3 className="mt-1 text-xl font-black">Revenue over the last 7 days</h3></div><span className="rounded-full bg-primary/10 px-2.5 py-1 text-[10px] font-black uppercase tracking-wider text-primary">Live from sold sales</span></div><div className="mt-8 grid h-64 grid-cols-7 items-end gap-3 border-b border-white/[0.08]">{values.map((value, index) => <div key={index} className="group flex h-full flex-col items-center justify-end gap-2"><span className="text-[10px] text-white/0 transition group-hover:text-white/60">${value.toFixed(0)}</span><div style={{ height: `${Math.max(value ? 8 : 2, (value / max) * 86)}%` }} className={`w-full rounded-t-lg transition ${index === values.length - 1 ? "bg-primary shadow-[0_0_20px_#00e5c240]" : "bg-primary/25 group-hover:bg-primary/60"}`} /></div>)}</div><div className="mt-3 grid grid-cols-7 text-center text-[10px] text-white/30">{days.map((day) => <span key={day.toISOString()}>{day.toLocaleDateString(undefined, { weekday: "short" })}</span>)}</div></section><section className="rounded-2xl border border-white/[0.07] bg-[#101313] p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="text-xs text-white/40">Product performance</p><h3 className="mt-1 text-xl font-black">Best sellers</h3></div><span className="text-xs text-white/35">Units sold</span></div><div className="mt-6 space-y-4">{analytics?.bestSellers.map((item, index) => <div key={item.name} className="flex items-center gap-4"><span className="w-5 text-xs text-white/30">{index + 1}</span><span className="w-40 truncate text-sm font-bold">{item.name}</span><div className="h-2 flex-1 rounded-full bg-white/[0.06]"><div style={{ width: `${Math.max(15, 100 - index * 18)}%` }} className="h-full rounded-full bg-primary" /></div><span className="w-16 text-right text-xs text-white/45">{item.units}</span></div>)}{!analytics?.bestSellers.length && <p className="text-sm text-white/35">No sales data yet.</p>}</div></section></div>; }

function SalesWorkspace({ products, conversations, sales, sale, setSale, currency, setCurrency, onSubmit, onReceipt, onRefresh, setNotice }: { products: Product[]; conversations: Conversation[]; sales: Sale[]; sale: { productId: string; quantity: string; customerId: string; customerName: string }; setSale: (value: typeof sale) => void; currency: Currency; setCurrency: (value: Currency) => void; onSubmit: (event: FormEvent) => void; onReceipt: (sale: Sale) => void; onRefresh: () => void; setNotice: (value: string) => void }) { const [subpage, setSubpage] = useState<"record" | "history">("record"); const [productFilter, setProductFilter] = useState("ALL"); const [statusFilter, setStatusFilter] = useState("ALL"); const [statusSale, setStatusSale] = useState<Sale | null>(null); const [status, setStatus] = useState<"SOLD" | "RETURNED" | "REFUNDED">("SOLD"); const [note, setNote] = useState(""); const filtered = sales.filter((item) => (productFilter === "ALL" || item.productId === productFilter) && (statusFilter === "ALL" || (item.status || "SOLD") === statusFilter)); async function updateStatus(event: FormEvent) { event.preventDefault(); if (!statusSale) return; const response = await fetch(`/api/sales/${statusSale.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ status, note }) }); const data = await response.json(); setNotice(response.ok ? `Sale marked ${status.toLowerCase()}. Inventory and analytics updated.` : data.error); if (response.ok) { setStatusSale(null); setNote(""); onRefresh(); } } return <div className="space-y-6"><div className="flex items-center gap-2 rounded-2xl border border-white/[0.07] bg-[#101313] p-2"><button onClick={() => setSubpage("record")} className={`flex-1 rounded-xl px-4 py-3 text-sm font-black transition ${subpage === "record" ? "bg-primary text-bg" : "text-white/40 hover:bg-white/[0.04] hover:text-white"}`}>Record a new sale</button><button onClick={() => setSubpage("history")} className={`flex-1 rounded-xl px-4 py-3 text-sm font-black transition ${subpage === "history" ? "bg-primary text-bg" : "text-white/40 hover:bg-white/[0.04] hover:text-white"}`}>Sales history <span className="ml-1 rounded-full bg-white/[0.08] px-1.5 py-0.5 text-[10px]">{sales.length}</span></button></div>{subpage === "record" ? <section className="rounded-2xl border border-white/[0.07] bg-[#101313] p-6 sm:p-8"><div className="max-w-xl"><span className="rounded-full bg-primary/10 px-2.5 py-1 text-[10px] font-black uppercase tracking-wider text-primary">Sales terminal</span><h3 className="mt-4 text-2xl font-black">Record a new sale</h3><p className="mt-2 text-sm leading-relaxed text-white/40">Choose a CRM customer or enter a walk-in customer. Sold inventory and revenue update automatically.</p></div><form onSubmit={onSubmit} className="mt-8 grid gap-4 sm:grid-cols-2"><label className="text-xs font-bold text-white/50 sm:col-span-2">Product<select required value={sale.productId} onChange={(event) => setSale({ ...sale, productId: event.target.value })} className="mt-2 w-full rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-3 text-sm"><option value="">Select product</option>{products.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.stock} available</option>)}</select></label><label className="text-xs font-bold text-white/50">CRM customer<select value={sale.customerId} onChange={(event) => { const customer = conversations.find((item) => item.id === event.target.value); setSale({ ...sale, customerId: event.target.value, customerName: customer?.customerName || "" }); }} className="mt-2 w-full rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-3 text-sm"><option value="">Choose from CRM inbox</option>{conversations.map((item) => <option key={item.id} value={item.id}>{item.customerName} · {item.channel}</option>)}</select></label><label className="text-xs font-bold text-white/50">Customer name<input value={sale.customerName} onChange={(event) => setSale({ ...sale, customerName: event.target.value })} placeholder="Walk-in customer" className="mt-2 w-full rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-3 text-sm" /></label><label className="text-xs font-bold text-white/50">Quantity<input required min="1" type="number" value={sale.quantity} onChange={(event) => setSale({ ...sale, quantity: event.target.value })} className="mt-2 w-full rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-3 text-sm" /></label><button type="submit" className="sale-submit mt-2 rounded-xl bg-primary px-6 py-3 text-sm font-black text-bg sm:col-span-2">Complete sale</button></form></section> : <section className="overflow-hidden rounded-2xl border border-white/[0.07] bg-[#101313]"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/[0.07] p-5"><div><h3 className="font-black">Sales history</h3><p className="mt-1 text-xs text-white/35">Mark transactions sold, returned, or refunded with an explanation.</p></div><div className="flex flex-wrap items-center justify-end gap-2"><CurrencySelect currency={currency} setCurrency={setCurrency} /><select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)} className="rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-2 text-xs text-white/60"><option value="ALL">All statuses</option><option value="SOLD">Sold</option><option value="RETURNED">Returned</option><option value="REFUNDED">Refunded</option></select><select value={productFilter} onChange={(event) => setProductFilter(event.target.value)} className="rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-2 text-xs text-white/60"><option value="ALL">All products</option>{products.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></div></div><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left text-sm"><thead className="bg-white/[0.02] text-[11px] uppercase tracking-wider text-white/30"><tr><th className="px-6 py-4">Product</th><th>Customer</th><th>Qty</th><th>Total</th><th>Status</th><th>Date</th><th className="pr-6 text-right">Actions</th></tr></thead><tbody>{filtered.map((item) => <tr key={item.id} className="border-t border-white/[0.05] hover:bg-white/[0.02]"><td className="px-6 py-4 font-bold">{item.productName}</td><td className="text-white/50">{item.customerName || "Walk-in customer"}</td><td>{item.quantity}</td><td className="font-bold text-primary">{formatMoney(convertMoney(item.total, item.currency, currency), currency)}</td><td><span className={`rounded-full px-2.5 py-1 text-[10px] font-black ${(item.status || "SOLD") === "SOLD" ? "bg-primary/10 text-primary" : (item.status || "SOLD") === "RETURNED" ? "bg-amber-300/10 text-amber-300" : "bg-rose-400/10 text-rose-300"}`}>{item.status || "SOLD"}</span></td><td className="text-xs text-white/40">{new Date(item.createdAt).toLocaleString()}</td><td className="pr-6 text-right"><button title="View receipt" onClick={() => onReceipt(item)} className="mr-1 rounded-lg p-2 text-white/45 hover:bg-primary/10 hover:text-primary"><Icon name="receipt" size={16} /></button><button title="Change sale status" onClick={() => { setStatusSale(item); setStatus((item.status || "SOLD") as "SOLD" | "RETURNED" | "REFUNDED"); setNote(item.note || ""); }} className="rounded-lg p-2 text-amber-300/70 hover:bg-amber-300/10 hover:text-amber-300"><Icon name="edit" size={16} /></button></td></tr>)}</tbody></table>{!filtered.length && <p className="px-6 py-12 text-center text-sm text-white/35">No sales match the selected filters.</p>}</div></section>}{statusSale && <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/70 p-5 backdrop-blur-sm"><form onSubmit={updateStatus} className="w-full max-w-md rounded-3xl border border-white/10 bg-[#121616] p-6 shadow-2xl"><p className="text-[10px] font-black uppercase tracking-[0.2em] text-primary">Update sale</p><h3 className="mt-3 text-xl font-black">{statusSale.productName}</h3><label className="mt-6 block text-xs font-bold text-white/50">Status<select value={status} onChange={(event) => setStatus(event.target.value as "SOLD" | "RETURNED" | "REFUNDED")} className="mt-2 w-full rounded-xl border border-white/10 bg-white/[0.025] px-3 py-3 text-sm"><option value="SOLD">Sold</option><option value="RETURNED">Returned</option><option value="REFUNDED">Refunded</option></select></label><label className="mt-4 block text-xs font-bold text-white/50">Reason / note<textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="Explain the return or refund…" className="mt-2 min-h-24 w-full rounded-xl border border-white/10 bg-white/[0.025] px-3 py-3 text-sm outline-none focus:border-primary" /></label><div className="mt-6 flex gap-3"><button type="button" onClick={() => setStatusSale(null)} className="flex-1 rounded-xl border border-white/10 py-3 text-sm font-bold text-white/55">Cancel</button><button className="flex-1 rounded-xl bg-primary py-3 text-sm font-black text-bg">Save status</button></div></form></div>}</div>; }

function SalesHistory({ products, sales, sale, setSale, onSubmit, onReceipt }: { products: Product[]; sales: Sale[]; sale: { productId: string; quantity: string; customerName: string }; setSale: (value: typeof sale) => void; onSubmit: (event: FormEvent) => void; onReceipt: (sale: Sale) => void }) { const [productFilter, setProductFilter] = useState("ALL"); const filtered = productFilter === "ALL" ? sales : sales.filter((item) => item.productId === productFilter); return <div className="space-y-6"><div className="grid gap-4 sm:grid-cols-3"><Stat label="Total revenue" value={`$${sales.reduce((sum, item) => sum + item.total, 0).toFixed(2)}`} icon="chart" /><Stat label="Products sold" value={String(new Set(sales.map((item) => item.productId)).size)} icon="box" tone="amber" /><Stat label="Transactions" value={String(sales.length)} icon="receipt" tone="violet" /></div><section className="rounded-2xl border border-white/[0.07] bg-[#101313] p-5 sm:p-6"><div><span className="rounded-full bg-primary/10 px-2.5 py-1 text-[10px] font-black uppercase tracking-wider text-primary">Sales terminal</span><h3 className="mt-4 text-2xl font-black">Record a new sale</h3><p className="mt-2 text-sm text-white/40">Complete a sale and Orquestra updates inventory, analytics, and the sales history automatically.</p></div><form onSubmit={onSubmit} className="mt-6 grid gap-3 sm:grid-cols-4"><select required value={sale.productId} onChange={(event) => setSale({ ...sale, productId: event.target.value })} className="rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-3 text-sm"><option value="">Select product</option>{products.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.stock} available</option>)}</select><input required min="1" type="number" value={sale.quantity} onChange={(event) => setSale({ ...sale, quantity: event.target.value })} className="rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-3 text-sm" placeholder="Quantity" /><input value={sale.customerName} onChange={(event) => setSale({ ...sale, customerName: event.target.value })} placeholder="Customer name" className="rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-3 text-sm" /><button className="rounded-xl bg-primary px-4 text-sm font-black text-bg">Complete sale</button></form></section><section className="overflow-hidden rounded-2xl border border-white/[0.07] bg-[#101313]"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/[0.07] p-5"><div><h3 className="font-black">Sales overview</h3><p className="mt-1 text-xs text-white/35">Track every sold product and open its receipt.</p></div><select value={productFilter} onChange={(event) => setProductFilter(event.target.value)} className="rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-2 text-xs text-white/60"><option value="ALL">All sold products</option>{products.filter((product) => sales.some((item) => item.productId === product.id)).map((product) => <option key={product.id} value={product.id}>{product.name}</option>)}</select></div><div className="overflow-x-auto"><table className="w-full min-w-[700px] text-left text-sm"><thead className="bg-white/[0.02] text-[11px] uppercase tracking-wider text-white/30"><tr><th className="px-6 py-4">Product sold</th><th>Customer</th><th>Quantity</th><th>Total</th><th>Date</th><th className="pr-6 text-right">Receipt</th></tr></thead><tbody>{filtered.map((item) => <tr key={item.id} className="border-t border-white/[0.05] hover:bg-white/[0.02]"><td className="px-6 py-4 font-bold">{item.productName}</td><td className="text-white/50">{item.customerName || "Walk-in customer"}</td><td>{item.quantity}</td><td className="font-bold text-primary">{formatMoney(item.total, item.currency || "USD")}</td><td className="text-xs text-white/40">{new Date(item.createdAt).toLocaleString()}</td><td className="pr-6 text-right"><button title="View receipt" aria-label={`View receipt for ${item.productName}`} onClick={() => onReceipt(item)} className="rounded-lg p-2 text-white/45 transition hover:bg-primary/10 hover:text-primary"><Icon name="receipt" size={17} /></button></td></tr>)}</tbody></table>{!filtered.length && <p className="px-6 py-12 text-center text-sm text-white/35">No sales recorded yet.</p>}</div></section></div>; }

function ReceiptModal({ sale, onClose }: { sale: Sale; onClose: () => void }) { return <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/70 p-5 backdrop-blur-sm"><div className="w-full max-w-md rounded-3xl border border-white/10 bg-[#121616] p-6 shadow-2xl"><div className="flex items-start justify-between"><div><span className="rounded-full bg-primary/10 px-2.5 py-1 text-[10px] font-black uppercase tracking-wider text-primary">Receipt</span><h3 className="mt-4 text-2xl font-black">{sale.productName}</h3><p className="mt-1 text-sm text-white/40">Transaction {sale.id.slice(0, 8).toUpperCase()}</p></div><button onClick={onClose} className="text-2xl text-white/40">×</button></div><div className="mt-7 space-y-3 rounded-2xl bg-white/[0.035] p-4 text-sm"><div className="flex justify-between"><span className="text-white/40">Status</span><span className="font-bold">{sale.status || "SOLD"}</span></div><div className="flex justify-between"><span className="text-white/40">Customer</span><span className="font-bold">{sale.customerName || "Walk-in customer"}</span></div><div className="flex justify-between"><span className="text-white/40">Quantity</span><span className="font-bold">{sale.quantity}</span></div><div className="flex justify-between"><span className="text-white/40">Date</span><span className="font-bold">{new Date(sale.createdAt).toLocaleString()}</span></div>{sale.note && <div className="border-t border-white/10 pt-3"><span className="text-white/40">Note</span><p className="mt-1 font-bold">{sale.note}</p></div>}<div className="mt-3 flex justify-between border-t border-white/10 pt-3 text-base"><span className="font-black">Total</span><span className="font-black text-primary">{formatMoney(sale.total, sale.currency || "USD")}</span></div></div><button onClick={onClose} className="mt-6 w-full rounded-xl bg-primary py-3 text-sm font-black text-bg">Done</button></div></div>; }

function LogoutModal({ onCancel, onConfirm }: { onCancel: () => void; onConfirm: () => void }) { return <div className="dashboard-modal-backdrop"><div className="dashboard-logout-modal"><p className="text-[10px] font-black uppercase tracking-[0.22em] text-rose-300">End session</p><h3 className="mt-2 text-2xl font-black">Sign out of Orquestra?</h3><p className="mt-3 text-sm leading-relaxed text-white/45">Your workspace is safe. You can sign back in whenever you are ready.</p><div className="mt-8 grid grid-cols-2 gap-3"><button onClick={onCancel} className="dashboard-modal-cancel">Stay signed in</button><button onClick={onConfirm} className="dashboard-modal-confirm">Sign out</button></div></div></div>; }

function InventoryCatalog({ products, lowStock, product, setProduct, onAdd, onRefresh, setNotice }: { products: Product[]; lowStock: Product[]; product: { name: string; category: ProductCategory; details: Record<string, string>; sku: string; price: string; currency: Currency; stock: string; reorderLevel: string }; setProduct: (value: typeof product) => void; onAdd: (event: FormEvent) => void; onRefresh: () => void; setNotice: (value: string) => void }) {
  const [subpage, setSubpage] = useState<"add" | "products">("products");
  const [search, setSearch] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("ALL");
  const [editing, setEditing] = useState<Product | null>(null);
  const [viewing, setViewing] = useState<Product | null>(null);
  const [editDraft, setEditDraft] = useState<Partial<Product> & { details: Record<string, string> }>({ details: {} });
  const filteredProducts = products.filter((item) => { const haystack = [item.name, item.sku, item.category, ...Object.values(item.details || {})].join(" ").toLowerCase(); return (categoryFilter === "ALL" || (item.category || "GENERAL") === categoryFilter) && haystack.includes(search.toLowerCase()); });
  async function remove(productId: string) { if (!window.confirm("Remove this product from inventory?")) return; const response = await fetch(`/api/products/${productId}`, { method: "DELETE" }); const data = await response.json(); setNotice(response.ok ? "Product removed." : data.error); if (response.ok) onRefresh(); }
  function beginEdit(item: Product) { setEditing(item); setEditDraft({ ...item, details: { ...(item.details || {}) } }); }
  async function saveEdit(event: FormEvent) { event.preventDefault(); if (!editing || !window.confirm("Save these product changes?")) return; const response = await fetch(`/api/products/${editing.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(editDraft) }); const data = await response.json(); setNotice(response.ok ? "Product updated." : data.error); if (response.ok) { setEditing(null); onRefresh(); } }
  const category = productCategories[product.category];
  return <div className="space-y-6"><div className="grid gap-4 sm:grid-cols-3"><Stat label="Total products" value={String(products.length)} icon="box" tone="amber" /><Stat label="Low stock alerts" value={String(lowStock.length)} icon="bell" tone="violet" /><Stat label="Units on hand" value={String(products.reduce((sum, item) => sum + item.stock, 0))} icon="chart" /></div><section className="overflow-hidden rounded-2xl border border-white/[0.07] bg-[#101313]"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/[0.07] p-5 sm:p-6"><div><div className="flex items-center gap-2"><button onClick={() => setSubpage("add")} className={`border-b-2 pb-2 text-sm font-black ${subpage === "add" ? "border-primary text-white" : "border-transparent text-white/35"}`}>Add products</button><button onClick={() => setSubpage("products")} className={`border-b-2 pb-2 text-sm font-black ${subpage === "products" ? "border-primary text-white" : "border-transparent text-white/35"}`}>Products <span className="ml-1 rounded-full bg-white/[0.07] px-1.5 py-0.5 text-[10px] text-white/45">{products.length}</span></button></div><p className="mt-3 text-xs text-white/35">{subpage === "add" ? "Choose a category and add the fields that describe the product." : "Search, filter, view, edit, or remove every product in your catalog."}</p></div>{subpage === "products" && <button onClick={() => setSubpage("add")} className="flex items-center gap-2 rounded-xl bg-primary px-3.5 py-2 text-xs font-black text-bg"><Icon name="plus" size={14} /> Add product</button>}</div>{subpage === "add" ? <form onSubmit={onAdd} className="p-5 sm:p-6"><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Field label="Product name" required value={product.name} onChange={(value) => setProduct({ ...product, name: value })} placeholder="e.g. Galaxy S24" /><label className="text-xs font-bold text-white/50">Category<select value={product.category} onChange={(event) => setProduct({ ...product, category: event.target.value as ProductCategory, details: {} })} className="mt-2 w-full rounded-xl border border-white/[0.07] bg-white/[0.025] px-3 py-2.5 text-sm outline-none focus:border-primary">{Object.entries(productCategories).map(([key, value]) => <option key={key} value={key}>{value.label}</option>)}</select></label><Field label="SKU" value={product.sku} onChange={(value) => setProduct({ ...product, sku: value })} placeholder="Optional SKU" /><Field label="Price" required type="number" value={product.price} onChange={(value) => setProduct({ ...product, price: value })} placeholder="0.00" /><label className="text-xs font-bold text-white/50">Currency<select value={product.currency} onChange={(event) => setProduct({ ...product, currency: event.target.value as Currency })} className="mt-2 w-full rounded-xl border border-white/[0.07] bg-white/[0.025] px-3 py-2.5 text-sm">{currencies.map((item) => <option key={item.code} value={item.code}>{item.label}</option>)}</select></label><Field label="Stock" required type="number" value={product.stock} onChange={(value) => setProduct({ ...product, stock: value })} placeholder="0" /><Field label="Reorder level" type="number" value={product.reorderLevel} onChange={(value) => setProduct({ ...product, reorderLevel: value })} placeholder="5" />{category.fields.map((field) => <Field key={field.key} label={field.label} type={field.type} value={product.details[field.key] || ""} onChange={(value) => setProduct({ ...product, details: { ...product.details, [field.key]: value } })} placeholder={field.placeholder} />)}</div><div className="mt-6 flex items-center justify-between rounded-xl bg-white/[0.025] p-4"><p className="text-xs text-white/40">{category.label} fields are ready. You can add more details later by editing the product.</p><button className="rounded-xl bg-primary px-5 py-2.5 text-sm font-black text-bg">Save product</button></div></form> : <div><div className="flex flex-wrap gap-3 border-b border-white/[0.07] p-5"><label className="flex min-w-[220px] flex-1 items-center gap-2 rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-2.5 text-white/35"><Icon name="search" size={16} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search name, SKU, brand, color…" className="w-full bg-transparent text-sm text-white outline-none placeholder:text-white/25" /></label><select value={categoryFilter} onChange={(event) => setCategoryFilter(event.target.value)} className="rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-2.5 text-sm text-white/60"><option value="ALL">All categories</option>{Object.entries(productCategories).map(([key, value]) => <option key={key} value={key}>{value.label}</option>)}</select></div><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left text-sm"><thead className="bg-white/[0.02] text-[11px] uppercase tracking-wider text-white/30"><tr><th className="px-6 py-4">Product</th><th>Category</th><th>SKU</th><th>Stock</th><th>Price</th><th>Status</th><th className="pr-6 text-right">Actions</th></tr></thead><tbody>{filteredProducts.map((item) => <tr key={item.id} className="border-t border-white/[0.05] transition hover:bg-white/[0.02]"><td className="px-6 py-4"><p className="font-bold">{item.name}</p><p className="mt-1 max-w-[180px] truncate text-[11px] text-white/35">{Object.values(item.details || {}).filter(Boolean).join(" · ") || "No extra details"}</p></td><td><span className="rounded-full bg-white/[0.06] px-2.5 py-1 text-[10px] font-bold text-white/55">{productCategories[item.category || "GENERAL"].label}</span></td><td className="text-xs text-white/40">{item.sku}</td><td className={item.stock <= item.reorderLevel ? "font-bold text-amber-300" : "text-primary"}>{item.stock}</td><td>{formatMoney(item.price, item.currency || "USD")}</td><td><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold ${item.stock === 0 ? "bg-rose-400/10 text-rose-300" : item.stock <= item.reorderLevel ? "bg-amber-300/10 text-amber-300" : "bg-primary/10 text-primary"}`}>{item.stock === 0 ? "Out of stock" : item.stock <= item.reorderLevel ? "Low stock" : "In stock"}</span></td><td className="pr-6 text-right"><button title="View product" aria-label={`View ${item.name}`} onClick={() => setViewing(item)} className="mr-2 rounded-lg p-2 text-white/40 transition hover:bg-white/[0.07] hover:text-white"><Icon name="eye" size={16} /></button><button title="Edit product" aria-label={`Edit ${item.name}`} onClick={() => beginEdit(item)} className="mr-2 rounded-lg p-2 text-primary/70 transition hover:bg-primary/10 hover:text-primary"><Icon name="edit" size={16} /></button><button title="Remove product" aria-label={`Remove ${item.name}`} onClick={() => remove(item.id)} className="rounded-lg p-2 text-rose-300/70 transition hover:bg-rose-400/10 hover:text-rose-300"><Icon name="trash" size={16} /></button></td></tr>)}</tbody></table>{!filteredProducts.length && <p className="px-6 py-12 text-center text-sm text-white/35">No products match this search or category.</p>}</div></div>}</section>{editing && <EditProduct item={editing} draft={editDraft} setDraft={setEditDraft} onClose={() => setEditing(null)} onSave={saveEdit} />}{viewing && <ProductDetails product={viewing} onClose={() => setViewing(null)} />}</div>;
}

function ProductDetails({ product, onClose }: { product: Product; onClose: () => void }) { return <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/70 p-5 backdrop-blur-sm"><div className="w-full max-w-lg rounded-3xl border border-white/10 bg-[#121616] p-6 shadow-2xl"><div className="flex items-start justify-between"><div><span className="rounded-full bg-primary/10 px-2.5 py-1 text-[10px] font-black uppercase tracking-wider text-primary">{productCategories[product.category || "GENERAL"].label}</span><h3 className="mt-4 text-2xl font-black">{product.name}</h3><p className="mt-1 text-sm text-white/40">{product.sku}</p></div><button onClick={onClose} className="text-2xl text-white/40">×</button></div><div className="mt-7 grid grid-cols-3 gap-3"><div className="rounded-xl bg-white/[0.04] p-3"><p className="text-[10px] text-white/35">Price</p><p className="mt-1 font-black">{formatMoney(product.price, product.currency || "USD")}</p></div><div className="rounded-xl bg-white/[0.04] p-3"><p className="text-[10px] text-white/35">Stock</p><p className="mt-1 font-black">{product.stock}</p></div><div className="rounded-xl bg-white/[0.04] p-3"><p className="text-[10px] text-white/35">Reorder at</p><p className="mt-1 font-black">{product.reorderLevel}</p></div></div><div className="mt-6 space-y-3">{Object.entries(product.details || {}).filter(([, value]) => value).map(([key, value]) => <div key={key} className="flex justify-between border-b border-white/[0.06] pb-3 text-sm"><span className="capitalize text-white/40">{key.replace(/([A-Z])/g, " $1")}</span><span className="max-w-[60%] text-right font-bold">{value}</span></div>)}{!Object.values(product.details || {}).some(Boolean) && <p className="text-sm text-white/35">No category-specific details added.</p>}</div><button onClick={onClose} className="mt-7 w-full rounded-xl border border-white/10 py-2.5 text-sm font-bold text-white/65">Close</button></div></div>; }

function InventoryManager({ products, lowStock, product, setProduct, onAdd, onRefresh, setNotice }: { products: Product[]; lowStock: Product[]; product: { name: string; category: ProductCategory; details: Record<string, string>; sku: string; price: string; currency: Currency; stock: string; reorderLevel: string }; setProduct: (value: typeof product) => void; onAdd: (event: FormEvent) => void; onRefresh: () => void; setNotice: (value: string) => void }) {
  const [subpage, setSubpage] = useState<"products" | "alerts">("products");
  const [editing, setEditing] = useState<Product | null>(null);
  const [editDraft, setEditDraft] = useState<Partial<Product> & { details: Record<string, string> }>({ details: {} });
  const visibleProducts = subpage === "alerts" ? lowStock : products;
  async function remove(productId: string) { if (!window.confirm("Remove this product from inventory?")) return; const response = await fetch(`/api/products/${productId}`, { method: "DELETE" }); const data = await response.json(); setNotice(response.ok ? "Product removed." : data.error); if (response.ok) onRefresh(); }
  function beginEdit(item: Product) { setEditing(item); setEditDraft({ ...item, details: { ...(item.details || {}) } }); }
  async function saveEdit(event: FormEvent) { event.preventDefault(); if (!editing) return; const response = await fetch(`/api/products/${editing.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(editDraft) }); const data = await response.json(); setNotice(response.ok ? "Product updated." : data.error); if (response.ok) { setEditing(null); onRefresh(); } }
  const category = productCategories[product.category];
  return <div className="space-y-6"><div className="grid gap-4 sm:grid-cols-3"><Stat label="Total products" value={String(products.length)} icon="box" tone="amber" /><Stat label="Low stock alerts" value={String(lowStock.length)} icon="bell" tone="violet" /><Stat label="Units on hand" value={String(products.reduce((sum, item) => sum + item.stock, 0))} icon="chart" /></div><section className="overflow-hidden rounded-2xl border border-white/[0.07] bg-[#101313]"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/[0.07] p-5 sm:p-6"><div><div className="flex items-center gap-2"><button onClick={() => setSubpage("products")} className={`border-b-2 pb-2 text-sm font-black ${subpage === "products" ? "border-primary text-white" : "border-transparent text-white/35"}`}>Products</button><button onClick={() => setSubpage("alerts")} className={`border-b-2 pb-2 text-sm font-black ${subpage === "alerts" ? "border-primary text-white" : "border-transparent text-white/35"}`}>Stock alerts <span className="ml-1 rounded-full bg-amber-300/10 px-1.5 py-0.5 text-[10px] text-amber-300">{lowStock.length}</span></button></div><p className="mt-3 text-xs text-white/35">{subpage === "products" ? "View, edit, remove, and add products across every category." : "Products that have reached their reorder threshold."}</p></div><button onClick={() => document.getElementById("add-product")?.scrollIntoView({ behavior: "smooth" })} className="flex items-center gap-2 rounded-xl bg-primary px-3.5 py-2 text-xs font-black text-bg"><Icon name="plus" size={14} /> Add product</button></div><div className="overflow-x-auto"><table className="w-full min-w-[780px] text-left text-sm"><thead className="bg-white/[0.02] text-[11px] uppercase tracking-wider text-white/30"><tr><th className="px-6 py-4">Product</th><th>Category</th><th>SKU</th><th>Stock</th><th>Price</th><th className="pr-6 text-right">Actions</th></tr></thead><tbody>{visibleProducts.map((item) => <tr key={item.id} className="border-t border-white/[0.05] transition hover:bg-white/[0.02]"><td className="px-6 py-4"><p className="font-bold">{item.name}</p><p className="mt-1 text-[11px] text-white/35">{Object.values(item.details || {}).filter(Boolean).slice(0, 2).join(" · ") || "No extra details"}</p></td><td><span className="rounded-full bg-white/[0.06] px-2.5 py-1 text-[10px] font-bold text-white/55">{productCategories[item.category || "GENERAL"].label}</span></td><td className="text-xs text-white/40">{item.sku}</td><td className={item.stock <= item.reorderLevel ? "font-bold text-amber-300" : "text-primary"}>{item.stock}</td><td>{formatMoney(item.price, item.currency || "USD")}</td><td className="pr-6 text-right"><button onClick={() => beginEdit(item)} className="mr-3 text-xs font-bold text-primary hover:text-secondary">Edit</button><button onClick={() => remove(item.id)} className="text-xs font-bold text-rose-300 hover:text-rose-200">Remove</button></td></tr>)}</tbody></table>{!visibleProducts.length && <p className="px-6 py-12 text-center text-sm text-white/35">{subpage === "alerts" ? "Everything is above its reorder level." : "No products have been added yet."}</p>}</div><form id="add-product" onSubmit={onAdd} className="border-t border-white/[0.07] p-5 sm:p-6"><div className="mb-4"><h3 className="text-sm font-black">Add a product</h3><p className="mt-1 text-xs text-white/35">Choose a category to reveal the fields that matter for that product.</p></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Field label="Product name" required value={product.name} onChange={(value) => setProduct({ ...product, name: value })} placeholder="e.g. Galaxy S24" /><label className="text-xs font-bold text-white/50">Category<select value={product.category} onChange={(event) => setProduct({ ...product, category: event.target.value as ProductCategory, details: {} })} className="mt-2 w-full rounded-xl border border-white/[0.07] bg-white/[0.025] px-3 py-2.5 text-sm outline-none focus:border-primary">{Object.entries(productCategories).map(([key, value]) => <option key={key} value={key}>{value.label}</option>)}</select></label><Field label="SKU" value={product.sku} onChange={(value) => setProduct({ ...product, sku: value })} placeholder="Optional SKU" /><Field label="Price" required type="number" value={product.price} onChange={(value) => setProduct({ ...product, price: value })} placeholder="0.00" /><label className="text-xs font-bold text-white/50">Currency<select value={product.currency} onChange={(event) => setProduct({ ...product, currency: event.target.value as Currency })} className="mt-2 w-full rounded-xl border border-white/[0.07] bg-white/[0.025] px-3 py-2.5 text-sm">{currencies.map((item) => <option key={item.code} value={item.code}>{item.label}</option>)}</select></label><Field label="Stock" required type="number" value={product.stock} onChange={(value) => setProduct({ ...product, stock: value })} placeholder="0" /><Field label="Reorder level" type="number" value={product.reorderLevel} onChange={(value) => setProduct({ ...product, reorderLevel: value })} placeholder="5" />{category.fields.map((field) => <Field key={field.key} label={field.label} type={field.type} value={product.details[field.key] || ""} onChange={(value) => setProduct({ ...product, details: { ...product.details, [field.key]: value } })} placeholder={field.placeholder} />)}</div><button className="mt-5 rounded-xl bg-primary px-4 py-2.5 text-sm font-black text-bg">Save product</button></form></section>{editing && <EditProduct item={editing} draft={editDraft} setDraft={setEditDraft} onClose={() => setEditing(null)} onSave={saveEdit} />}</div>;
}

function Field({ label, value, onChange, placeholder, type = "text", required = false }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string; type?: "text" | "number" | "date"; required?: boolean }) { return <label className="text-xs font-bold text-white/50">{label}<input required={required} type={type} value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} className="mt-2 w-full rounded-xl border border-white/[0.07] bg-white/[0.025] px-3 py-2.5 text-sm outline-none focus:border-primary" /></label>; }

function EditProduct({ item, draft, setDraft, onClose, onSave }: { item: Product; draft: Partial<Product> & { details: Record<string, string> }; setDraft: (value: Partial<Product> & { details: Record<string, string> }) => void; onClose: () => void; onSave: (event: FormEvent) => void }) { const category = productCategories[(draft.category || item.category || "GENERAL") as ProductCategory]; return <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/70 p-5 backdrop-blur-sm"><form onSubmit={onSave} className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-3xl border border-white/10 bg-[#121616] p-6 shadow-2xl"><div className="flex items-start justify-between"><div><p className="text-[10px] font-black uppercase tracking-[0.2em] text-primary">Edit product</p><h3 className="mt-2 text-2xl font-black">{item.name}</h3></div><button type="button" onClick={onClose} className="text-2xl text-white/40">×</button></div><div className="mt-6 grid gap-4 sm:grid-cols-2"><Field label="Product name" required value={String(draft.name || "")} onChange={(value) => setDraft({ ...draft, name: value })} placeholder="Product name" /><label className="text-xs font-bold text-white/50">Category<select value={draft.category || item.category || "GENERAL"} onChange={(event) => setDraft({ ...draft, category: event.target.value as ProductCategory, details: {} })} className="mt-2 w-full rounded-xl border border-white/[0.07] bg-white/[0.025] px-3 py-2.5 text-sm outline-none focus:border-primary">{Object.entries(productCategories).map(([key, value]) => <option key={key} value={key}>{value.label}</option>)}</select></label><Field label="SKU" value={String(draft.sku || "")} onChange={(value) => setDraft({ ...draft, sku: value })} placeholder="SKU" /><Field label="Price" required type="number" value={String(draft.price ?? "")} onChange={(value) => setDraft({ ...draft, price: Number(value) })} placeholder="0.00" /><label className="text-xs font-bold text-white/50">Currency<select value={draft.currency || "USD"} onChange={(event) => setDraft({ ...draft, currency: event.target.value as Currency })} className="mt-2 w-full rounded-xl border border-white/[0.07] bg-white/[0.025] px-3 py-2.5 text-sm">{currencies.map((item) => <option key={item.code} value={item.code}>{item.label}</option>)}</select></label><Field label="Stock" required type="number" value={String(draft.stock ?? "")} onChange={(value) => setDraft({ ...draft, stock: Number(value) })} placeholder="0" /><Field label="Reorder level" type="number" value={String(draft.reorderLevel ?? "5")} onChange={(value) => setDraft({ ...draft, reorderLevel: Number(value) })} placeholder="5" />{category.fields.map((field) => <Field key={field.key} label={field.label} type={field.type} value={draft.details[field.key] || ""} onChange={(value) => setDraft({ ...draft, details: { ...draft.details, [field.key]: value } })} placeholder={field.placeholder} />)}</div><div className="mt-7 flex justify-end gap-3"><button type="button" onClick={onClose} className="rounded-xl border border-white/10 px-4 py-2.5 text-sm font-bold text-white/55">Cancel</button><button className="rounded-xl bg-primary px-4 py-2.5 text-sm font-black text-bg">Save changes</button></div></form></div>; }

function SalesView({ products, sale, setSale, onSubmit }: { products: Product[]; sale: { productId: string; quantity: string; customerName: string }; setSale: (value: typeof sale) => void; onSubmit: (event: FormEvent) => void }) { return <div className="space-y-6"><section className="rounded-2xl border border-white/[0.07] bg-[#101313] p-6 sm:p-8"><div className="max-w-xl"><span className="rounded-full bg-primary/10 px-2.5 py-1 text-[10px] font-black uppercase tracking-wider text-primary">Sales terminal</span><h3 className="mt-4 text-2xl font-black">Record a new sale</h3><p className="mt-2 text-sm leading-relaxed text-white/40">Complete a sale once and Orquestra updates inventory and analytics automatically.</p></div><form onSubmit={onSubmit} className="mt-8 grid gap-4 sm:grid-cols-2"><label className="text-xs font-bold text-white/50 sm:col-span-2">Product<select required value={sale.productId} onChange={(event) => setSale({ ...sale, productId: event.target.value })} className="mt-2 w-full rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-3 text-sm outline-none focus:border-primary"><option value="">Select a product</option>{products.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.stock} available</option>)}</select></label><label className="text-xs font-bold text-white/50">Quantity<input required min="1" type="number" value={sale.quantity} onChange={(event) => setSale({ ...sale, quantity: event.target.value })} className="mt-2 w-full rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-3 text-sm outline-none focus:border-primary" /></label><label className="text-xs font-bold text-white/50">Customer name<input value={sale.customerName} onChange={(event) => setSale({ ...sale, customerName: event.target.value })} placeholder="Walk-in customer" className="mt-2 w-full rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-3 text-sm outline-none focus:border-primary" /></label><button className="mt-2 flex items-center justify-center gap-2 rounded-xl bg-primary py-3 text-sm font-black text-bg sm:col-span-2">Complete sale <Icon name="arrow" size={15} /></button></form></section></div>; }

function CrmView({ conversations, messages, selected, setSelected, filter, setFilter, reply, setReply, onReply }: { conversations: Conversation[]; messages: CrmMessage[]; selected: string; setSelected: (value: string) => void; filter: string; setFilter: (value: string) => void; reply: string; setReply: (value: string) => void; onReply: (event: FormEvent) => void }) { const filtered = conversations.filter((item) => filter === "ALL" || item.channel === filter); const conversation = conversations.find((item) => item.id === selected); return <div className="grid min-h-[620px] overflow-hidden rounded-2xl border border-white/[0.07] bg-[#101313] lg:grid-cols-[300px_1fr]"><aside className="border-b border-white/[0.07] lg:border-b-0 lg:border-r"><div className="flex items-center justify-between border-b border-white/[0.07] p-5"><div><h3 className="font-black">Inbox</h3><p className="mt-1 text-xs text-white/35">{conversations.length} conversations</p></div><button className="rounded-lg bg-primary/10 p-2 text-primary"><Icon name="plus" size={15} /></button></div><div className="p-4"><select value={filter} onChange={(event) => setFilter(event.target.value)} className="w-full rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-2.5 text-xs text-white/65"><option value="ALL">All channels</option>{["WHATSAPP", "WECHAT", "LINE", "MESSENGER", "VIBER", "TELEGRAM", "SMS", "GMAIL", "OUTLOOK"].map((channel) => <option key={channel}>{channel}</option>)}</select><div className="mt-4 space-y-1.5">{filtered.map((item) => <button key={item.id} onClick={() => setSelected(item.id)} className={`w-full rounded-xl p-3 text-left transition ${selected === item.id ? "bg-primary/10 ring-1 ring-primary/25" : "hover:bg-white/[0.04]"}`}><div className="flex items-center justify-between gap-2"><span className="truncate text-sm font-bold">{item.customerName}</span><span className="text-[9px] font-black text-primary">{item.channel}</span></div><p className="mt-1 truncate text-[11px] text-white/35">{item.customerAddress}</p></button>)}{!filtered.length && <p className="px-2 py-8 text-center text-xs text-white/30">No conversations yet.</p>}</div></div></aside><section className="flex min-h-[620px] flex-col"><div className="border-b border-white/[0.07] p-5"><div className="flex items-center justify-between"><div><h3 className="font-black">{conversation?.customerName || "Select a conversation"}</h3><p className="mt-1 text-xs text-white/35">{conversation ? `${conversation.channel} · ${conversation.customerAddress}` : "Your connected channels will appear here."}</p></div>{conversation && <span className="rounded-full bg-primary/10 px-2.5 py-1 text-[10px] font-bold text-primary">{conversation.status}</span>}</div></div><div className="flex-1 space-y-4 overflow-y-auto p-5">{messages.map((item) => <div key={item.id} className={`flex ${item.direction === "OUTBOUND" ? "justify-end" : "justify-start"}`}><div className={`max-w-[80%] rounded-2xl px-4 py-3 text-sm ${item.direction === "OUTBOUND" ? "rounded-br-md bg-primary text-bg" : "rounded-bl-md bg-white/[0.05] text-white/80"}`}><p className={`mb-1 text-[10px] font-bold ${item.direction === "OUTBOUND" ? "text-bg/60" : "text-white/35"}`}>{item.senderName} · {item.direction === "OUTBOUND" ? "You" : "Customer"}</p>{item.body}</div></div>)}{conversation && !messages.length && <p className="py-12 text-center text-sm text-white/30">No messages in this conversation yet.</p>}</div><form onSubmit={onReply} className="flex gap-3 border-t border-white/[0.07] p-4"><input required disabled={!selected} value={reply} onChange={(event) => setReply(event.target.value)} placeholder={selected ? `Reply via ${conversation?.channel || "channel"}…` : "Select a conversation first"} className="min-w-0 flex-1 rounded-xl border border-white/[0.08] bg-white/[0.025] px-4 py-3 text-sm outline-none focus:border-primary disabled:opacity-40" /><button disabled={!selected} className="flex items-center gap-2 rounded-xl bg-primary px-4 text-sm font-black text-bg disabled:opacity-40">Send <Icon name="arrow" size={14} /></button></form></section></div>; }

function DraftPage({ setNotice }: { setNotice: (value: string) => void }) {
  const [messages, setMessages] = useState<{ id: string; senderName: string; body: string; mentionUserId?: string; attachment?: { name: string; size: number; type: string; dataUrl: string }; createdAt: string }[]>([]);
  const [agents, setAgents] = useState<{ id: string; name: string; email: string; role: string }[]>([]);
  const [body, setBody] = useState("");
  const [mention, setMention] = useState("");
  const [file, setFile] = useState<{ name: string; size: number; type: string; dataUrl: string } | undefined>();
  const [loading, setLoading] = useState(true);
  async function load() { const [messageResponse, agentResponse] = await Promise.all([fetch("/api/messages"), fetch("/api/invitations")]); if (messageResponse.ok) setMessages((await messageResponse.json()).messages); if (agentResponse.ok) setAgents((await agentResponse.json()).members); setLoading(false); }
  useEffect(() => { load(); }, []);
  function chooseFile(event: React.ChangeEvent<HTMLInputElement>) { const selected = event.target.files?.[0]; if (!selected) return; if (selected.size > 20 * 1024 * 1024) { setNotice("Attachments must be 20MB or smaller."); event.target.value = ""; return; } const reader = new FileReader(); reader.onload = () => setFile({ name: selected.name, size: selected.size, type: selected.type, dataUrl: String(reader.result) }); reader.readAsDataURL(selected); }
  async function submit(event: FormEvent) { event.preventDefault(); const response = await fetch("/api/messages", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ body, mentionUserId: mention || undefined, attachment: file }) }); const data = await response.json(); setNotice(response.ok ? "Draft shared with the team." : data.error); if (response.ok) { setBody(""); setMention(""); setFile(undefined); load(); } }
  return <div className="draft-page dashboard-card grid min-h-[620px] overflow-hidden rounded-2xl border border-white/[0.07] bg-[#101313] lg:grid-cols-[1fr_300px]"><section className="flex min-h-[620px] flex-col"><div className="border-b border-white/[0.07] p-6"><p className="text-[10px] font-black uppercase tracking-[0.2em] text-primary">Growth collaboration</p><h3 className="mt-2 text-2xl font-black">Draft</h3><p className="mt-1 text-sm text-white/40">Talk with your owner and agents, mention teammates, and share working files.</p></div><div className="draft-message-list flex-1 space-y-4 overflow-y-auto p-6">{loading && <p className="text-sm text-white/35">Loading team conversation...</p>}{!loading && !messages.length && <p className="py-16 text-center text-sm text-white/35">No drafts yet. Start the team conversation below.</p>}{messages.map((message) => <article key={message.id} className="rounded-2xl border border-white/[0.06] bg-white/[0.02] p-4"><div className="flex items-center justify-between gap-3"><p className="text-sm font-black">{message.senderName}</p><time className="text-[10px] text-white/30">{new Date(message.createdAt).toLocaleString()}</time></div>{message.body && <p className="mt-2 whitespace-pre-wrap text-sm leading-relaxed text-white/70">{message.body}</p>}{message.attachment && <a download={message.attachment.name} href={message.attachment.dataUrl} className="mt-3 flex items-center gap-3 rounded-xl border border-primary/15 bg-primary/[0.05] p-3 text-xs text-primary"><span className="text-lg">↗</span><span><b className="block">{message.attachment.name}</b><small className="text-white/40">{(message.attachment.size / 1024 / 1024).toFixed(2)}MB · Download attachment</small></span></a>}</article>)}</div><form onSubmit={submit} className="border-t border-white/[0.07] p-5"><textarea value={body} onChange={(event) => setBody(event.target.value)} placeholder="Write a draft or update for the team..." className="min-h-24 w-full resize-none rounded-2xl border border-white/[0.08] bg-white/[0.025] p-4 text-sm outline-none focus:border-primary" /><div className="mt-3 flex flex-wrap items-center gap-3"><label className="cursor-pointer rounded-xl border border-white/[0.1] px-3 py-2 text-xs font-bold text-white/55 transition hover:border-primary hover:text-primary"><input type="file" className="hidden" onChange={chooseFile} />Attach file</label>{file && <span className="max-w-48 truncate text-xs text-primary">{file.name}</span>}<button className="ml-auto rounded-xl bg-primary px-5 py-2.5 text-sm font-black text-bg">Share draft</button></div></form></section><aside className="border-t border-white/[0.07] p-5 lg:border-l lg:border-t-0"><p className="text-[10px] font-black uppercase tracking-[0.2em] text-primary">Mention teammate</p><h4 className="mt-2 font-black">Keep work moving</h4><p className="mt-1 text-xs leading-relaxed text-white/35">Select an agent to mention in your draft.</p><select value={mention} onChange={(event) => setMention(event.target.value)} className="mt-5 w-full rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-3 text-sm"><option value="">No mention</option>{agents.map((agent) => <option key={agent.id} value={agent.id}>{agent.name} · {agent.role}</option>)}</select><div className="mt-6 rounded-2xl border border-primary/15 bg-primary/[0.04] p-4"><p className="text-xs font-black text-primary">Attachment limit</p><p className="mt-1 text-xs leading-relaxed text-white/45">Images, PDFs, documents, and other files up to 20MB are supported.</p></div></aside></div>;
}

function OrchestrationPage({ setNotice }: { setNotice: (value: string) => void }) {
  const [agents, setAgents] = useState<{ id: string; name: string; email: string; role: string; status: string }[]>([]);
  const [form, setForm] = useState({ name: "", email: "", role: "SALES" });
  const [loaded, setLoaded] = useState(false);
  async function loadAgents() { const response = await fetch("/api/invitations"); if (response.ok) { const data = await response.json(); setAgents(data.invitations); } setLoaded(true); }
  useEffect(() => { loadAgents(); }, []);
  async function submit(event: FormEvent) { event.preventDefault(); const response = await fetch("/api/invitations", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(form) }); const data = await response.json(); setNotice(response.ok ? (data.emailSent ? "Agent created and invitation email sent." : "Agent created. Email delivery needs attention.") : data.error); if (response.ok) { setForm({ name: "", email: "", role: "SALES" }); loadAgents(); } }
  return <div className="orchestration-page space-y-6"><section className="orchestration-hero rounded-2xl border border-primary/20 bg-[#101b19] p-6 sm:p-8"><div className="flex flex-wrap items-start justify-between gap-6"><div><span className="text-[10px] font-black uppercase tracking-[0.2em] text-primary">Growth workspace</span><h3 className="mt-3 text-2xl font-black">Orchestrate your team</h3><p className="mt-2 max-w-xl text-sm leading-relaxed text-white/50">Add up to five role-based agents. Each invitation receives scoped access and a secure login email.</p></div><div className="orchestration-count"><strong>{agents.length}</strong><span>/ 5 agents</span></div></div></section><section className="rounded-2xl border border-white/[0.07] bg-[#101313] p-5 sm:p-6"><div><p className="text-[10px] font-black uppercase tracking-[0.2em] text-primary">Add an agent</p><h3 className="mt-2 text-xl font-black">Build your operating team</h3><p className="mt-1 text-xs text-white/35">Assign one focused role to each teammate.</p></div><form onSubmit={submit} className="mt-6 grid gap-3 md:grid-cols-[1fr_1.2fr_1fr_auto]"><input required disabled={agents.length >= 5} placeholder="Agent name" value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} className="rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-3 text-sm outline-none focus:border-primary disabled:opacity-40" /><input required disabled={agents.length >= 5} type="email" placeholder="Agent email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} className="rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-3 text-sm outline-none focus:border-primary disabled:opacity-40" /><select disabled={agents.length >= 5} value={form.role} onChange={(event) => setForm({ ...form, role: event.target.value })} className="rounded-xl border border-white/[0.08] bg-white/[0.025] px-3 py-3 text-sm disabled:opacity-40"><option value="SALES">Sales agent</option><option value="INVENTORY">Inventory agent</option><option value="ANALYTICS">Analytics agent</option><option value="CRM">CRM agent</option></select><button disabled={agents.length >= 5} className="rounded-xl bg-primary px-5 py-3 text-sm font-black text-bg disabled:cursor-not-allowed disabled:opacity-40">{agents.length >= 5 ? "Limit reached" : "Add agent"}</button></form></section><section className="rounded-2xl border border-white/[0.07] bg-[#101313] p-5 sm:p-6"><div className="flex items-center justify-between"><div><h3 className="font-black">Your agents</h3><p className="mt-1 text-xs text-white/35">Role-based access for this Growth workspace.</p></div><span className="text-xs font-bold text-white/35">{loaded ? `${agents.length} active` : "Loading..."}</span></div><div className="mt-5 grid gap-3 md:grid-cols-2">{agents.map((agent) => <div key={agent.id} className="flex items-center gap-4 rounded-2xl border border-white/[0.06] bg-white/[0.02] p-4"><span className="grid h-10 w-10 place-items-center rounded-xl bg-primary/10 text-primary"><Icon name="users" size={18} /></span><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{agent.name}</p><p className="truncate text-xs text-white/35">{agent.email}</p></div><div className="text-right"><p className="text-[10px] font-black text-primary">{agent.role}</p><p className="mt-1 text-[10px] text-white/30">{agent.status}</p></div></div>)}{loaded && !agents.length && <p className="py-10 text-center text-sm text-white/35 md:col-span-2">No agents yet. Add your first teammate above.</p>}</div></section></div>;
}

function InviteCard({ invite, setInvite, onSubmit }: { invite: { name: string; email: string; role: string }; setInvite: (value: typeof invite) => void; onSubmit: (event: FormEvent) => void }) { return <section className="mt-6 rounded-2xl border border-primary/15 bg-primary/[0.04] p-5 sm:p-6"><div className="flex flex-wrap items-start justify-between gap-4"><div><span className="text-[10px] font-black uppercase tracking-[0.2em] text-primary">Team orchestration</span><h3 className="mt-2 text-lg font-black">Invite an agent</h3><p className="mt-1 text-xs text-white/40">Create scoped access for your Growth or Enterprise workspace.</p></div></div><form onSubmit={onSubmit} className="mt-5 grid gap-3 md:grid-cols-4"><input required placeholder="Agent name" value={invite.name} onChange={(event) => setInvite({ ...invite, name: event.target.value })} className="rounded-xl border border-white/[0.08] bg-black/10 px-3 py-2.5 text-sm outline-none focus:border-primary" /><input required type="email" placeholder="Agent email" value={invite.email} onChange={(event) => setInvite({ ...invite, email: event.target.value })} className="rounded-xl border border-white/[0.08] bg-black/10 px-3 py-2.5 text-sm outline-none focus:border-primary" /><select value={invite.role} onChange={(event) => setInvite({ ...invite, role: event.target.value })} className="rounded-xl border border-white/[0.08] bg-black/10 px-3 py-2.5 text-sm outline-none focus:border-primary"><option value="SALES">Sales agent</option><option value="INVENTORY">Inventory agent</option><option value="ANALYTICS">Analytics agent</option><option value="CRM">CRM agent</option></select><button className="rounded-xl bg-primary px-3 py-2.5 text-sm font-black text-bg">Create invite</button></form></section>; }
